import {accessories,byId,finishes,productSvg} from './catalog-data.js';
import {recommend,compatibleAccessories,storageNeeds,cabinetFacts,priceProject} from './solution-engine.js';
const esc=s=>String(s??'').replaceAll('&','&amp;').replaceAll('"','&quot;').replaceAll('<','&lt;');
export function entryHTML(){return `<h2 tabindex="-1">Choose your starting point.</h2><p>Plan a whole kitchen, choose individual cabinets, or improve storage in cabinets you already own.</p><div class="solution-entry-grid">${[['whole','Design My Whole Kitchen','Plan your kitchen cabinets, choose your favorite finishes, and discover smart storage solutions.','Start My Kitchen Plan','finish-soft-white-room-v2.png'],['individual','Shop Individual Cabinets','Choose the cabinet sizes and styles you need, with optional organization upgrades.','Choose My Cabinets','products/standard-base.svg'],['accessories','Shop Storage Accessories','Find organizers and storage upgrades for cabinets you already own.','Find Storage Solutions','accessory-drawers.png']].map(([id,title,copy,cta,image])=>`<button type="button" class="solution-entry-card" data-solution-path="${id}"><img src="/kabbie/assets/${image}" alt="${title} illustrative reference"><span><strong>${title}</strong><small>${copy}</small><b>${cta} →</b></span></button>`).join('')}</div><p class="caption">Illustrative imagery. Basic cabinet features, origin, accessory availability and final pricing require specification review.</p>`;}
export function basicHTML(c){const facts=cabinetFacts[c.product],included=facts?.verifiedInclusions||[];const p=byId(c.product),f=finishes.find(f=>f.id===c.finish);return `<section class="basic-cabinet-info"><div class="basic-visual-pair"><div>${p?productSvg(p,{width:c.width,style:c.style,finish:c.finish}):''}<small>Your cabinet planning illustration</small></div><figure><img src="/kabbie/assets/${included.length?'accessory-dishes.png':f?.image||'finish-natural-oak-room-v2.png'}" alt="${included.length?'Standard door cabinet with included shelves':(f?.name||'Kitchen')+' illustrative finish inspiration'}" loading="lazy"><figcaption>${included.length?'Basic cabinet storage · shelves included · illustrative reference':'Finish inspiration · not the exact cabinet'}</figcaption></figure></div><span class="eyebrow">Your cabinet first</span><h3>Everything you need for everyday storage.</h3>${included.length?'<p>Your cabinet comes with the standard functional features listed below. Add specialized organizers only if they make your space work better.</p><strong>Included with your cabinet</strong><ul>'+included.map(i=>'<li>'+esc(i)+'</li>').join('')+'</ul>':'<p>Start with the basic cabinet. The team will confirm the included doors, shelves, drawer components and hardware for this model in your written specification.</p><p class="caption">No premium organizer is assumed included. Base features and price: confirmation required.</p>'}</section>`;}
export function storageHTML(c,context){const basic=c.basicStorage===true,needs=context.needs||[],suggestions=recommend(c,needs),all=compatibleAccessories(c),show=c.browseStorage||!suggestions.length;return basicHTML(c)+`<h2 tabindex="-1">Want to make your cabinet work even harder?</h2><p>Explore organization upgrades designed to keep everything easier to reach and neatly stored.</p>${bundleChoiceHTML(c,all,suggestions)}${basic?'<p class="notice" role="status">Keeping basic storage. No optional organizers are selected for this cabinet.</p>':`<fieldset class="storage-needs"><legend>Storage options for this cabinet</legend>${storageNeeds.filter(n=>all.some(a=>a.id===n.accessory)).map(n=>`<label class="storage-need-visual"><img src="/kabbie/assets/${accessories.find(a=>a.id===n.accessory).image}" alt="" loading="lazy"><span><input type="checkbox" data-storage-need="${n.id}" ${needs.includes(n.id)?'checked':''}>${n.label}</span></label>`).join('')}<label><input type="checkbox" data-storage-need="basic" ${needs.includes('basic')?'checked':''}>I’m happy with basic storage</label></fieldset>${needs.includes('basic')?'<p class="notice">Basic storage chosen. No recommendations are shown.</p>':`<p class="caption">Showing storage matched to this cabinet type and ${c.width}″ planning width. Final internal fit still needs confirmation.</p><h3>${suggestions.length?'Recommended for Your Cabinet':'Explore compatible storage'}</h3><div class="config-options">${(show?all:suggestions.map(r=>r.accessory)).map(a=>{const n=storageNeeds.find(n=>n.accessory===a.id);return `<article class="compatibility-card"><img src="/kabbie/assets/${a.image}" alt="${a.name} illustrative accessory reference" loading="lazy"><h3>${n?.benefit||a.purpose}</h3><p>${a.name}</p><p class="caption">${n?.explanation||'Organize everyday items.'} ${suggestions.some(r=>r.accessory.id===a.id)?'Recommended because of your selected storage need and cabinet planning match.':''}</p><p class="caption">${a.min}–${a.max}″ planning cabinet widths · internal clearance and availability to confirm. ${a.fitNote?esc(a.fitNote):''}</p><p class="caption">Regular price: Quote required · bundle pricing to confirm.</p><button type="button" class="btn outline" data-accessory-id="${a.id}" aria-pressed="${c.accessories.includes(a.id)}">${c.accessories.includes(a.id)?'Remove organizer':'Add to My Cabinet'}</button><details><summary>See how it works</summary><p>${n?.explanation||a.purpose} The image is an illustrative storage reference, not a verified product photograph.</p></details>${c.accessories.includes(a.id)?'<button type="button" class="textlink" data-apply-accessory="'+a.id+'">Apply to other matching cabinets</button>':''}</article>`;}).join('')}</div>${!all.length?'<p class="notice">No accessory planning match for this cabinet. Keep basic storage or review a different cabinet.</p>':''}${all.length?'<button class="textlink" type="button" id="browse-compatible">Browse all compatible accessories</button>':''}`}`}`;}

export function layoutChoices(selected){return `<fieldset class="order-layout-choices"><legend>Kitchen layout</legend>${[['One-wall',null],['Galley','layout-galley.png'],['L-shaped','banner-compact-ivory.png'],['U-shaped','finish-soft-white-room-v2.png'],['Island kitchen','color-charcoal-gray.png'],['Not sure',null]].map(([label,image])=>`<label>${image?`<img src="/kabbie/assets/${image}" alt="${label} kitchen design inspiration" loading="lazy">`:`<div class="order-layout-diagram" aria-hidden="true">${label==='One-wall'?'<svg viewBox="0 0 200 120"><rect x="20" y="20" width="160" height="80" fill="none" stroke="#b6aa96"/><path d="M35 35H165" stroke="#8b7655" stroke-width="16"/></svg>':'<span>Let’s plan it together</span>'}</div>`}<span><input type="radio" name="layout" value="${label}" required ${selected===label?'checked':''}>${label}</span></label>`).join('')}</fieldset><p class="caption">Illustrative layout and finish inspiration; final fit depends on your room.</p>`;}

function bundleChoiceHTML(c,all,suggestions){
 const a=all.find(a=>c.accessories.includes(a.id))||suggestions[0]?.accessory||all[0],p=byId(c.product);if(!a)return '<button type="button" class="btn outline" id="keep-basic">Keep My Basic Cabinet</button>';
 const ids=c.accessories.length?c.accessories:[a.id];let totals;try{totals=priceProject([{...c,accessories:ids}],[]);}catch{totals={total:null,bundleDiscount:0};}const money=value=>value===null?'Quote required':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(value/100),separate=totals.total===null?null:totals.total+totals.bundleDiscount;
 return `<section class="bundle-decision" aria-label="Compare basic cabinet and cabinet with storage"><div class="bundle-intro"><span class="eyebrow">Make more of your cabinet</span><h3>Better organization.<br>Potential bundle savings.</h3><p>Choose the cabinet on its own, or bring it together with organizers that work for you. Ask us to compare eligible bundle pricing with buying the items separately.</p></div><div class="bundle-choice-grid"><article class="bundle-choice-card"><div class="bundle-preview-basic">${productSvg(p,{width:c.width,style:c.style,finish:c.finish})}</div><div class="bundle-choice-copy"><span class="eyebrow">Cabinet only</span><h3>A simple starting point.</h3><p>Your chosen cabinet, with base features confirmed in the specification.</p><p class="bundle-small">No optional organizers. Add storage later if your needs change.</p><button type="button" class="btn outline" id="keep-basic">Keep My Basic Cabinet</button></div></article><article class="bundle-choice-card bundle-choice-organized"><div class="bundle-preview-pair">${productSvg(p,{width:c.width,style:c.style,finish:c.finish})}<span aria-hidden="true">+</span><img src="/kabbie/assets/${a.image}" alt="${esc(a.name)} illustrative add-on reference" loading="lazy"></div><div class="bundle-choice-copy"><span class="eyebrow">Cabinet + compatible storage</span><h3>Plan it together. Check the savings.</h3><p>${storageNeeds.find(n=>n.accessory===a.id)?.explanation||a.purpose} Explore only organizers matched to your cabinet.</p><dl class="bundle-price-comparison"><dt>Cabinet + organizers bought separately</dt><dd>${money(separate)}</dd><dt>Eligible bundle price</dt><dd>${money(totals.total)}</dd><dt>${totals.bundleDiscount>0?'Estimated bundle savings':'Potential savings'}</dt><dd>${totals.bundleDiscount>0?money(totals.bundleDiscount):'Confirm in your quote'}</dd></dl><button type="button" class="btn outline" id="explore-upgrades">Explore My Cabinet + Storage Bundle</button></div></article></div><p class="caption">Illustrative cabinet and organizer previews. ${c.accessories.length?'Comparison reflects your selected organizers.':'Organizer shown as an example only; nothing is added automatically.'} Bundle offers depend on eligible items and confirmed pricing. ${c.bundleQuote?'A separate-versus-bundle comparison is included in your quote request.':'Both choices are optional; your cabinet can be requested without upgrades.'}</p></section>`;
}
